      },
      {
        "panahon": "Kalagitnaan ng ika-20 siglo",
        "yugto": "Paghina at Pagpapabaya",
        "deskripsyon": "Tulad ng maraming parke sa NYC, ang Prospect Park ay dumanas ng matinding pagpapabaya mula 1960s hanggang 1970s dahil sa krisis sa badyet ng lungsod. Naging sira-sira ang mga pasilidad, nasira ang mga landscape, at tumaas ang antas ng krimen, na nagresulta sa pagbaba ng bilang ng mga bumibisita."
      },
      {
        "panahon": "1987-Kasalukuyan",
        "yugto": "Pagpapanumbalik at Muling Pagsilang",
        "deskripsyon": "Ang pagkatatag ng Prospect Park Alliance noong 1987 ang naging simula ng muling pagbangon ng parke. Ang non-profit na organisasyong ito, sa pakikipagtulungan sa Lungsod ng New York, ay nangalap ng daan-daang milyong dolyar para sa malawakang restorasyon. Isinaayos ang mga makasaysayang istruktura, pinanumbalik ang mga landscape, at pinabuti ang mga pasilidad, na nagbalik sa dating ganda at sigla ng parke."
      }
    ],
    "mga_pangunahing_tampok_at_landmark": [
      {
        "pangalan": "Long Meadow",
        "deskripsyon": "Isang 90-acre na parang na sinasabing pinakamahabang tuloy-tuloy na urbanong parang sa Estados Unidos. Ito ang sentro ng disenyo ni Olmsted, na nagbibigay ng malawak at payapang tanawin."
      },
      {
        "pangalan": "The Ravine",
        "deskripsyon": "Isang makapal na gubat na may mga sapa at talon, na siyang nag-iisang natitirang gubat sa Brooklyn. Ito ay isang halimbawa ng 'picturesque' na disenyo na maingat na itinayo upang magmukhang natural."
      },
      {
        "pangalan": "Prospect Park Lake",
        "deskripsyon": "Isang 60-acre na lawa na gawa ng tao, sikat para sa pamamangka, pangingisda, at pagmamasid sa mga ibon."
      },
      {
        "pangalan": "Grand Army Plaza",
        "deskripsyon": "Ang maringal na pasukan sa parke na nagtatampok sa Soldiers' and Sailors' Arch, Bailey Fountain, at mga monumento bilang parangal sa mga bayani ng digmaan."
      },
      {
        "pangalan": "The Boathouse",
        "deskripsyon": "Isang magandang istrukturang Beaux-Arts na itinayo noong 1905 sa tabi ng Lullwater. Muntik na itong gibain noong 1960s ngunit nailigtas ng mga preservationist. Ngayon ay isang visitor center at event space."
      },
      {
        "pangalan": "Lefferts Historic House",
        "deskripsyon": "Isang makasaysayang bahay-bukid ng mga Dutch mula sa ika-18 siglo na inilipat sa parke noong 1918. Nagsisilbi itong museo na nagpapakita ng buhay sa Brooklyn noong unang panahon."
      }
    ],
    "prospect_park_ngayon": {
      "status": "Mananatiling 'puso' ng Brooklyn, isang mahalagang espasyo para sa libangan, kultura, at komunidad. Ito ay patuloy na pinamamahalaan at pinapanatili ng Prospect Park Alliance katuwang ang NYC Parks, na tinitiyak na mananatili itong isang world-class na parke para sa mga susunod na henerasyon."
    }
  }
}
